mapper.select:
SELECT conversation_id, buyer_id, seller_id, last_message_at, last_preview,
       buyer_unread, seller_unread, created_at
FROM conversation WHERE conversation_id = #{conversationId}

mapper.update:
UPDATE conversation SET last_message_at = #{lastMessageAt}, last_preview = #{lastPreview},
                        buyer_unread = #{buyerUnread}, seller_unread = #{sellerUnread}
WHERE conversation_id = #{conversationId}

UPDATE conversation
SET buyer_unread = 0 SET seller_unread = 0
WHERE conversation_id = #{conversationId}
